const first = $input.first()?.json || {};
const body = first.body || first;
const slugs = body.slugs || [];
const endpoint = body.endpoint || 'posts';
if (!Array.isArray(slugs) || slugs.length === 0) {
  throw new Error('Body must include {"slugs": ["slug1", ...]}');
}
return slugs.map(slug => ({ json: { slug, endpoint } }));

const builds = $('Build Items').all();
const responses = $input.all();
const out = [];
for (let i = 0; i < builds.length; i++) {
  const slug = builds[i].json.slug;
  const resp = responses[i]?.json;
  let post = null;
  if (Array.isArray(resp) && resp.length > 0) post = resp[0];
  else if (resp && resp.id) post = resp;
  else if (resp && Array.isArray(resp.body)) post = resp.body[0];
  if (post) {
    out.push({ json: { slug, endpoint: builds[i].json.endpoint || 'posts', post_id: post.id, post_title: (post.title && (post.title.rendered || post.title)) || '', post_url: post.link, found: true } });
  }
}
if (out.length === 0) {
  return [{ json: { none_found: true } }];
}
return out;

const sheetData = $('GET Master Sheet').first().json.values || [];
const items = $('Resolve Found').all().filter(i => i.json.found === true);
const data = [];
const rowsFound = [];
const rowsMissing = [];
for (const item of items) {
  const url = item.json.post_url;
  let row_idx = -1;
  for (let r = 1; r < sheetData.length; r++) {
    const urlInRow = (sheetData[r][7] || '').trim();
    if (urlInRow === url || urlInRow === url.replace(/\/$/, '') || urlInRow + '/' === url) {
      row_idx = r + 1; // 1-indexed
      break;
    }
  }
  if (row_idx > 0) {
    data.push({ range: 'Blog!B' + row_idx, values: [['Eliminado']] });
    rowsFound.push({ slug: item.json.slug, row: row_idx });
  } else {
    rowsMissing.push(item.json.slug);
  }
}
const body = { valueInputOption: 'USER_ENTERED', data };
return [{ json: { sheet_batch_json: JSON.stringify(body), data_count: data.length, rows_found: rowsFound, rows_missing: rowsMissing } }];

const builds = $('Build Items').all().map(b => b.json.slug);
const foundItems = $('Resolve Found').all().filter(i => i.json.found === true);
const foundSlugs = foundItems.map(i => i.json.slug);
const notFoundSlugs = builds.filter(s => !foundSlugs.includes(s));
let sheetInfo = null;
try { sheetInfo = $('Build Sheet Batch Update').first()?.json; } catch (e) {}
const rowsUpdated = sheetInfo?.rows_found || [];
const rowsMissing = sheetInfo?.rows_missing || [];
const lines = [];
lines.push('🗑 *Cleanup Posts*');
lines.push('');
lines.push('Total slugs: ' + builds.length);
lines.push('Posts borrados (papelera WP): ' + foundSlugs.length);
for (const s of foundSlugs) lines.push('   ✅ ' + s);
if (notFoundSlugs.length > 0) {
  lines.push('');
  lines.push('Slugs no encontrados en WP: ' + notFoundSlugs.length);
  for (const s of notFoundSlugs) lines.push('   ⚠️ ' + s);
}
lines.push('');
lines.push('Sheet rows actualizadas a Eliminado: ' + rowsUpdated.length);
for (const r of rowsUpdated) lines.push('   ✅ ' + r.slug + ' (row ' + r.row + ')');
if (rowsMissing.length > 0) {
  lines.push('');
  lines.push('Sheet rows no encontradas: ' + rowsMissing.length);
  for (const s of rowsMissing) lines.push('   ⚠️ ' + s);
}
const telegram_message = lines.join('\n');
return [{ json: {
  telegram_message,
  summary: {
    total: builds.length,
    deleted_in_wp: foundSlugs,
    not_found_in_wp: notFoundSlugs,
    sheet_rows_updated: rowsUpdated,
    sheet_rows_missing: rowsMissing
  }
} }];
